def solve(N):
    def sum_of_digits(num):
        total = 0
        while num > 0:
            total += num % 10
            num //= 10
        return total

    def to_binary(num):
        return bin(num)[2:]

    digits_sum = sum_of_digits(N)
    binary_representation = to_binary(digits_sum)

    return binary_representation

